___CSS_LOADER_EXPORT___.push([module.id, `body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

html,
body,
#root {
  height: 100%;
  scroll-behavior: smooth;
}

/* Scroll style */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background-color: transparent;
  border-radius: 5px;
}

::-webkit-scrollbar-thumb {
  width: 5px;
  background-color: transparent;
}

input::-webkit-outer-spin-button,
input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

input[type=number] {
  -moz-appearance: textfield;
}

*:hover::-webkit-scrollbar-thumb,
*:focus::-webkit-scrollbar-thumb {
  background-color: #00000080;
  border-radius: 5px;
  border: 2px solid transparent;
  background-clip: content-box;
}

.buyNowContainer {
  bottom: 0;
  left: 0;
  z-index: 10;
  position: relative;
  box-shadow: 0px 0px 70px rgb(39 29 90) !important;
}

.buyNowContainerSticky {
  position: fixed;
  animation: transition 0.3s linear;
}

.MuiDataGrid-cell:focus {
  outline: none !important;
}

.border-line-top::before {
  content: '';
  padding: 5px;
  background: linear-gradient(269deg, #f448ab 24.22%, #7968ff 100%);
  position: absolute;
  top: 10px;
  left: 0px;
  width: 100vw;
}

.border-line-left::before {
  content: '';
  padding: 5px;
  background: linear-gradient(269deg, #f448ab 24.22%, #7968ff 100%);
  position: absolute;
  left: 10px;
  top: 0px;
  height: 150vh;
}

.border-line-left::after {
  content: '';
  padding: 5px;
  background: linear-gradient(269deg, #f448ab 24.22%, #7968ff 100%);
  position: absolute;
  bottom: 10px;
  right: 0px;
  width: 100vw;
}

.border-line-top::after {
  content: '';
  padding: 5px;
  background: linear-gradient(269deg, #f448ab 24.22%, #7968ff 100%);
  position: absolute;
  right: 10px;
  top: 0px;
  height: 150vh;
}

.borderNone {
  border: 'none' !important;
}

.gradient-border {
  background: linear-gradient(90deg, #ea7a8f 0.64%, #e452c8 99.36%);
  line-height: 0;
  border-radius: 100px;
  padding: 3px;
}

.product-chip {
  position: absolute;
  top: 30px;
  left: 30px;
  width: 100%;
}

